import React, { useEffect, useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { Clock, CheckCircle, XCircle, User, Users, Loader } from 'lucide-react';
import { useAuth } from '@/contexts/AuthContext';
import { useTranslation } from '@/contexts/LanguageContext';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useLecturerClasses } from '@/hooks/useClasses';
import { extractString, extractDate } from '@/utils/sqlNull';
import { apiService } from '@/services/api';
import AttendanceModal from '@/components/modals/AttendanceModal';
import { Card } from '@/components/ui';
import { logger } from '@/utils/logger';

type Day = 'Monday' | 'Tuesday' | 'Wednesday' | 'Thursday' | 'Friday';

type WeekDay = 'Sunday' | 'Monday' | 'Tuesday' | 'Wednesday' | 'Thursday' | 'Friday' | 'Saturday';

interface ScheduleItem {
  id: string;
  day: Day;
  startTime: string;
  endTime: string;
  courseCode: string;
  courseName: string;
  className: string;
  credits: number;
  room: string;
  topic: string;
  weekNumber: number;
  classId: number;
  actualDate?: Date;
  meetingId: number;
}

// Helper to extract day name from date string
const getDayFromDate = (dateValue: unknown): Day | null => {
  const date = extractDate(dateValue as any);
  if (!date) return null;
  const dayIndex = date.getDay();
  const daysMap: Record<number, Day> = {
    1: 'Monday',
    2: 'Tuesday',
    3: 'Wednesday',
    4: 'Thursday',
    5: 'Friday',
  };
  return daysMap[dayIndex] || null;
};

// Helper to extract time (HH:mm) from jam_pertemuan which may be time-only or ISO datetime
const getTimeFromDate = (dateValue: unknown): string => {
  const dateStr = extractString(dateValue as any);
  if (!dateStr) return '00:00';

  const timeOnlyMatch = dateStr.match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);
  if (timeOnlyMatch) {
    const hh = timeOnlyMatch[1].padStart(2,'0');
    const mm = timeOnlyMatch[2];
    return `${hh}:${mm}`;
  }

  const afterT = dateStr.split('T')[1];
  if (afterT) {
    const part = afterT.split('.')[0].split('Z')[0];
    const [hh = '00', mm = '00'] = part.split(':');
    return `${hh.padStart(2,'0')}:${mm.padStart(2,'0')}`;
  }

  try {
    const d = new Date(dateStr);
    if (!isNaN(d.getTime())) {
      return d.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false });
    }
  } catch {}

  return '00:00';
};

// Helper to get current week's start (Sunday) and end (Saturday)
const getCurrentWeekRange = (): { start: Date; end: Date } => {
  const today = new Date();
  const dayOfWeek = today.getDay();
  
  const daysToSunday = dayOfWeek === 0 ? 0 : dayOfWeek;
  
  const start = new Date(today);
  start.setDate(today.getDate() - daysToSunday);
  start.setHours(0, 0, 0, 0);
  
  const end = new Date(start);
  end.setDate(start.getDate() + 6);
  end.setHours(23, 59, 59, 999);
  
  return { start, end };
};

const LecturerDashboard: React.FC = () => {
  const { user, currentSemester } = useAuth();
  const { t } = useTranslation();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [thisWeekItems, setThisWeekItems] = useState<(ScheduleItem & { weekDay: WeekDay })[]>([]);
  const [selectedMeeting, setSelectedMeeting] = useState<{
    meetingId: number;
    classId: number;
    title: string;
    subtitle: string;
    dateLabel?: string;
    meetingDateTime?: Date;
    topic?: string;
  } | null>(null);
  const [togglingMeetingId, setTogglingMeetingId] = useState<number | null>(null);
  const [optimisticToggles, setOptimisticToggles] = useState<Record<number, boolean>>({});

  // Track component mount and query enablement
  useEffect(() => {
    // Component mounted
  }, []);

  useEffect(() => {
    const enabled = Boolean(user?.employeeId && currentSemester);
    logger.debug('LecturerDashboard - meetingRecapQuery enabled state:', enabled);
    // Query enabled state updated
  }, [user?.employeeId, currentSemester]);

  // Compute this week's range and fetch lecturer classes via React Query
  const { start, end } = React.useMemo(() => getCurrentWeekRange(), []);
  const startDay = start.toISOString().split('T')[0];
  const endDay = end.toISOString().split('T')[0];

  const { data: rawClasses, isLoading: loading } = useLecturerClasses(
    user?.employeeId || '',
    { semester: currentSemester, start_day: startDay, end_day: endDay }
  );

  // Use the new efficient meeting recap endpoint instead of N+1 queries
  // Allow employeeId '0' as valid — only require employeeId to be non-null/undefined
  const meetingRecapQueryEnabled = Boolean(user?.employeeId != null && currentSemester);

  const { data: meetingRecapData, isLoading: meetingRecapLoading } = useQuery({
    queryKey: ['lecturer-meeting-recap', user?.employeeId, currentSemester],
    queryFn: async () => {
      if (!user?.employeeId || !currentSemester) {
        return null;
      }

      try {
        const res = await apiService.getLecturerMeetingRecap(user.employeeId, { semester: currentSemester });
        return res;
      } catch (err) {
        throw err;
      }
    },
    enabled: meetingRecapQueryEnabled,
  });

  // Compute meeting recap data from the efficient endpoint
  const meetingRecaps = useMemo(() => {
    if (!meetingRecapData?.classes) return [];

    return meetingRecapData.classes.map((classData: any) => {
      // Normalize meetings with robust fallbacks and sort by pertemuan (weekNumber)
      const meetings = (Array.isArray(classData.meetings) ? classData.meetings : []).map((meeting: any) => {
        // Use `pertemuan_ke` as the authoritative meeting number
        let computedWeekNumber = Number(meeting.pertemuan_ke ?? meeting.pertemuanKe ?? meeting.pertemuan ?? 0);
        if (Number.isNaN(computedWeekNumber)) computedWeekNumber = 0;

        // Normalize attendance counts (strings/numbers) and prefer recorded_attendances over total_attendances
        const recordedRaw = meeting.recorded_attendances ?? meeting.recordedAttendances ?? meeting.total_attendances ?? meeting.total_attendances_count ?? 0;
        const recorded = Number(recordedRaw) || 0;

        // Normalize attendance_complete values (boolean or string/number variants)
        const acRaw = meeting.attendance_complete ?? meeting.attendanceComplete;
        const attendanceComplete = acRaw === true || acRaw === 'true' || acRaw === 1 || acRaw === '1';

        // Determine student attendance complete: prefer explicit flag, otherwise infer from counts
        const studentComplete = attendanceComplete || (classData.total_students ? recorded >= Number(classData.total_students) : recorded > 0);

        // Determine lecturer assigned: check if id_dosen exists and is not null/empty
        const lecturerAssigned = Boolean(meeting.id_dosen);

        const computed = {
          id: meeting.id,
          weekNumber: computedWeekNumber,
          date: meeting.tgl_pertemuan ? new Date(meeting.tgl_pertemuan) : null,
          topic: meeting.topik ?? meeting.topic ?? undefined,
          studentAttendanceComplete: Boolean(studentComplete),
          lecturerAssigned,
          totalStudents: Number(classData.total_students ?? 0),
          recordedAttendances: recorded,
          absensiAktif: Boolean(meeting.absensi_aktif ?? meeting.absensiAktif),
        };

        return computed;
      }).sort((a: any, b: any) => {
        // Primary sort by computed weekNumber, fallback to date
        if ((a.weekNumber ?? 0) !== (b.weekNumber ?? 0)) return (a.weekNumber ?? 0) - (b.weekNumber ?? 0);
        const aDate = a.date ? a.date.getTime() : 0;
        const bDate = b.date ? b.date.getTime() : 0;
        return aDate - bDate;
      });

      return {
        classId: classData.class_id,
        courseCode: classData.kode_mk,
        courseName: classData.course_name,
        className: classData.class_name,
        sksTatapMuka: classData.sks_tatap_muka,
        sksPraktek: classData.sks_praktek,
        sksPrakLapangan: classData.sks_prak_lapangan,
        sksSimulasi: classData.sks_simulasi,
        meetings,
      };
    });
  }, [meetingRecapData]);

  // Debug logs to inspect the raw API response and the computed meeting recaps
  useEffect(() => {
    if (meetingRecapData) {
      console.debug('LecturerDashboard - raw meetingRecapData:', meetingRecapData);
    }
    if (meetingRecaps && meetingRecaps.length) {
      console.debug('LecturerDashboard - mapped meetingRecaps:', meetingRecaps);
      meetingRecaps.forEach((c: any) => {
        console.debug(`LecturerDashboard - class ${c.classId} meetings:`, c.meetings.map((m: any) => ({ id: m.id, weekNumber: m.weekNumber, date: m.date, absensiAktif: m.absensiAktif, recorded: m.recordedAttendances, lecturerAssigned: m.lecturerAssigned, id_dosen: (m as any).id_dosen })));
      });
    }
  }, [meetingRecapData, meetingRecaps]);

  useEffect(() => {
    const items: ScheduleItem[] = [];
    (Array.isArray(rawClasses) ? rawClasses : []).forEach(classData => {
      if (!classData) {
        return;
      }
      if (!Array.isArray(classData.meeting_schedules)) {
        return;
      }
      classData.meeting_schedules.forEach(meeting => {
        if (!meeting) {
          return;
        }
        const day = getDayFromDate(meeting.tgl_pertemuan);
        
        if (!day) {
          return;
        }
        
        const startTime = getTimeFromDate(meeting.jam_pertemuan);
        const actualDate = extractDate(meeting.tgl_pertemuan as any);
        
        // Skip if no valid date
        if (!actualDate) {
          return;
        }
        
        const totalSKS = (classData.sks_tatap_muka || 0) + (classData.sks_praktek || 0) + (classData.sks_prak_lapangan || 0) + (classData.sks_simulasi || 0);
        const durationMinutes = totalSKS * 60;
        
        const [startHours, startMinutes] = startTime.split(':').map(Number);
        const totalMinutes = startHours * 60 + startMinutes + durationMinutes;
        const endHours = Math.floor(totalMinutes / 60) % 24;
        const endMinutes = totalMinutes % 60;
        const endTime = `${String(endHours).padStart(2, '0')}:${String(endMinutes).padStart(2, '0')}`;

        items.push({
          id: `${classData.kelas_id}-${meeting.id}`,
          day,
          startTime,
          endTime,
          courseCode: classData.kode_mk,
          courseName: classData.nama_mk,
          className: classData.nama_kelas,
          credits: totalSKS,
          room: extractString(meeting.media_pembelajaran, 'TBA'),
          topic: extractString(meeting.topik, ''),
          weekNumber: meeting.pertemuan_ke,
          classId: classData.kelas_id ?? 0,
          actualDate,
          meetingId: meeting.id,
        });
      });
    });

    // Backend already filtered by this week's date range, just add weekDay labels
    const weekItems: (ScheduleItem & { weekDay: WeekDay })[] = items
      .filter(item => item.actualDate) // Ensure valid date
      .map(item => {
        const weekDayIndex = item.actualDate!.getDay();
        const weekDaysMap: Record<number, WeekDay> = {
          0: 'Sunday',
          1: 'Monday',
          2: 'Tuesday',
          3: 'Wednesday',
          4: 'Thursday',
          5: 'Friday',
          6: 'Saturday',
        };
        return {
          ...item,
          weekDay: weekDaysMap[weekDayIndex] || 'Monday',
        };
      })
      .sort((a, b) => {
        if (!a.actualDate || !b.actualDate) return 0;
        return a.actualDate.getTime() - b.actualDate.getTime();
      });
    
    setThisWeekItems(weekItems);
  }, [rawClasses]);

  const handleToggleAttendance = async (e: React.MouseEvent, meetingId: number, currentStatus: boolean) => {
    e.stopPropagation();
    setTogglingMeetingId(meetingId);
    
    // Optimistic update
    setOptimisticToggles(prev => ({
      ...prev,
      [meetingId]: !currentStatus,
    }));
    
    try {
      await apiService.updateMeeting(meetingId, {
        absensi_aktif: !currentStatus,
      });
      
      // Invalidate both the meeting recap and class meetings queries to sync with AttendanceModal
      await queryClient.invalidateQueries({
        queryKey: ['lecturer-meeting-recap', user?.employeeId, currentSemester],
      });
      await queryClient.invalidateQueries({
        queryKey: ['class-meetings'],
      });
      
      // Clear optimistic toggle once data is confirmed
      setOptimisticToggles(prev => {
        const newToggles = { ...prev };
        delete newToggles[meetingId];
        return newToggles;
      });
    } catch (error) {
      console.error('Failed to toggle attendance:', error);
      // Revert optimistic update on error
      setOptimisticToggles(prev => {
        const newToggles = { ...prev };
        delete newToggles[meetingId];
        return newToggles;
      });
    } finally {
      setTogglingMeetingId(null);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-gray-900">Lecturer Dashboard</h1>
        <div className="text-sm text-gray-500">Academic Year 2024/2025</div>
      </div>

      {/* Meeting Recap Section */}
      <div className="card">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">{t('lecturer.meetings')}</h2>
        
        {meetingRecapLoading ? (
          <div className="text-center py-8 text-gray-500">{t('common.loading')}</div>
        ) : (
        <>
        {/* Legend */}
        <div className="mb-4 p-3 bg-gray-50 rounded-lg border border-gray-200">
          <h3 className="text-xs font-semibold text-gray-700 mb-2">{t('student.legend')}</h3>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-xs">
            <div key="student-complete" className="flex items-center gap-1.5">
              <CheckCircle className="h-4 w-4 text-green-600 flex-shrink-0" />
              <span className="text-gray-600">{t('student.attendanceRecapComplete')}</span>
            </div>
            <div key="student-partial" className="flex items-center gap-1.5">
              <CheckCircle className="h-4 w-4 text-orange-500 flex-shrink-0" />
              <span className="text-gray-600">{t('student.attendanceRecapPartial')}</span>
            </div>
            <div key="student-incomplete" className="flex items-center gap-1.5">
              <XCircle className="h-4 w-4 text-gray-300 flex-shrink-0" />
              <span className="text-gray-600">{t('student.attendanceRecapIncomplete')}</span>
            </div>
            <div key="lecturer-assigned" className="flex items-center gap-1.5">
              <User className="h-4 w-4 text-blue-600 flex-shrink-0" />
              <span className="text-gray-600">{t('lecturer.lecturerAssigned')}</span>
            </div>
            <div key="lecturer-unassigned" className="flex items-center gap-1.5">
              <User className="h-4 w-4 text-gray-300 flex-shrink-0" />
              <span className="text-gray-600">{t('lecturer.lecturerUnassigned')}</span>
            </div>
            <div key="attendance-active" className="flex items-center gap-1.5">
              <div className="h-2 w-2 rounded-full bg-green-600 flex-shrink-0" />
              <span className="text-gray-600">{t('lecturer.attendanceActive')}</span>
            </div>
            <div key="attendance-inactive" className="flex items-center gap-1.5">
              <div className="h-2 w-2 rounded-full bg-gray-400 flex-shrink-0" />
              <span className="text-gray-600">{t('lecturer.attendanceInactive')}</span>
            </div>
          </div>
        </div>
        
        {meetingRecaps.length === 0 ? (
          <div className="text-center py-8 text-gray-500">No classes found for this semester</div>
        ) : (
          <div className="space-y-3">
            {meetingRecaps.map(recap => {
              return (
              <Card key={recap.classId} className="p-0 overflow-hidden">
                {/* Class Info Header */}
                <div className="bg-gradient-to-r from-primary-50 to-secondary-50 px-3 py-2 border-b border-gray-200">
                  <div className="flex justify-between items-center gap-3">
                    <div className="flex-1 min-w-0">
                      <h4 className="font-semibold text-sm text-gray-900 truncate">
                        {recap.courseCode} - {recap.courseName}
                      </h4>
                      <p className="text-xs text-gray-600">{recap.className}</p>
                    </div>
                    <div className="flex items-center gap-2 flex-shrink-0">
                      <div className="text-xs text-gray-600">
                        {recap.meetings.length} meeting{recap.meetings.length !== 1 ? 's' : ''}
                      </div>
                      <button
                        type="button"
                        onClick={() => {
                          navigate(`/class-summary/${recap.classId}?courseCode=${encodeURIComponent(recap.courseCode)}&courseName=${encodeURIComponent(recap.courseName)}&className=${encodeURIComponent(recap.className)}&sksTatapMuka=${recap.sksTatapMuka}&sksPraktek=${recap.sksPraktek}&sksPrakLapangan=${recap.sksPrakLapangan}&sksSimulasi=${recap.sksSimulasi}&from=lecturer/dashboard`);
                        }}
                        className="px-2 py-1 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors flex items-center gap-1 text-xs whitespace-nowrap"
                        title="View attendance matrix"
                      >
                        <Users className="h-3.5 w-3.5" />
                        <span>Summary</span>
                      </button>
                    </div>
                  </div>
                </div>

                {/* Meeting Grid */}
                <div className="p-3">
                  <div className="flex gap-1 flex-wrap">
                    {recap.meetings.map((meeting: any) => {
                      const dateStr = meeting.date
                        ? meeting.date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
                        : ''; 
                      
                      // Use optimistic toggle if available, otherwise use actual value
                      const currentAbsensiAktif = optimisticToggles[meeting.id] !== undefined 
                        ? optimisticToggles[meeting.id] 
                        : meeting.absensiAktif;
                      
                      return (
                        <div
                          key={meeting.id}
                          role="button"
                          tabIndex={0}
                          onClick={() => {
                            const meetingDateTime = meeting.date ? new Date(meeting.date) : undefined;
                            console.log('LecturerDashboard Debug - Setting selectedMeeting with classId:', recap.classId);
                            setSelectedMeeting({
                              meetingId: meeting.id,
                              classId: recap.classId,
                              title: `${recap.courseCode} • ${recap.courseName}`,
                              subtitle: `Week ${meeting.weekNumber}`,
                              dateLabel: dateStr,
                              meetingDateTime,
                              topic: meeting.topic || undefined,
                            });
                          }}
                          onKeyDown={(event) => {
                            if (event.key === 'Enter' || event.key === ' ') {
                              event.preventDefault();
                              const meetingDateTime = meeting.date ? new Date(meeting.date) : undefined;
                              console.log('LecturerDashboard Debug - Setting selectedMeeting with classId:', recap.classId);
                              setSelectedMeeting({
                                meetingId: meeting.id,
                                classId: recap.classId,
                                title: `${recap.courseCode} • ${recap.courseName}`,
                                subtitle: `Week ${meeting.weekNumber}`,
                                dateLabel: dateStr,
                                meetingDateTime,
                                topic: meeting.topic || undefined,
                              });
                            }
                          }}
                          className="flex flex-col items-center gap-1 p-2 rounded border border-gray-200 hover:bg-gray-50 transition-colors cursor-pointer min-w-[80px] relative group focus:outline-none focus:ring-2 focus:ring-primary-200"
                          title={`Week ${meeting.weekNumber} - ${dateStr}${meeting.topic ? ` - ${meeting.topic}` : ''}\nStudent Attendance: ${meeting.recordedAttendances}/${meeting.totalStudents}\nLecturer Attendance: ${meeting.lecturerAssigned ? 'Complete' : 'Incomplete'}\nAttendance: ${meeting.absensiAktif ? 'Active' : 'Inactive'}`}
                        >
                          <div className="text-xs font-semibold text-gray-600">{meeting.weekNumber}</div>
                          
                          {/* Status Icons */}
                          <div className="flex gap-1 items-center justify-center h-6">
                            {/* Student Attendance Status */}
                            {meeting.studentAttendanceComplete ? (
                              <CheckCircle className="h-4 w-4 text-green-600" />
                            ) : meeting.recordedAttendances > 0 ? (
                              <CheckCircle className="h-4 w-4 text-orange-500" />
                            ) : (
                              <XCircle className="h-4 w-4 text-gray-300" />
                            )}
                            
                            {/* Lecturer Attendance Status (Complete if lecturer assigned) */}
                            {meeting.lecturerAssigned ? (
                              <User className="h-4 w-4 text-blue-600" />
                            ) : (
                              <User className="h-4 w-4 text-gray-300" />
                            )}
                          </div>
                          
                          <div className="text-xs text-gray-500 text-center leading-tight">
                            {dateStr || '-'}
                          </div>
                          
                          {/* Attendance activation status */}
                          <div className="flex items-center justify-center gap-1">
                            <div className={`h-2 w-2 rounded-full ${currentAbsensiAktif ? 'bg-green-600' : 'bg-gray-400'}`} />
                          </div>
                          
                          {/* Toggle Attendance Button */}
                          <button
                            type="button"
                            onClick={(e) => handleToggleAttendance(e, meeting.id, currentAbsensiAktif)}
                            disabled={togglingMeetingId === meeting.id}
                            aria-label={currentAbsensiAktif ? 'Deactivate attendance' : 'Activate attendance'}
                            onMouseEnter={(e) => {
                              (e.currentTarget as HTMLButtonElement).style.opacity = '1';
                            }}
                            onMouseLeave={(e) => {
                              (e.currentTarget as HTMLButtonElement).style.opacity = '0.25';
                            }}
                            className="absolute bottom-1 right-1 p-1.5 rounded bg-white border border-gray-200 hover:bg-gray-50 disabled:opacity-50 transition-opacity shadow-sm cursor-pointer"
                            style={{ opacity: 0.25 }}
                            title={currentAbsensiAktif ? 'Deactivate Attendance' : 'Activate Attendance'}
                          >
                            {togglingMeetingId === meeting.id ? (
                              <Loader className="h-3.5 w-3.5 text-gray-600 animate-spin" />
                            ) : (
                              <div className={`h-3.5 w-3.5 rounded-full border-2 ${currentAbsensiAktif ? 'bg-green-600 border-green-600' : 'border-gray-300'}`} />
                            )}
                          </button>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </Card>
              );
            })}
          </div>
        )}
        </>
        )}
      </div>

      <div className="card">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">{t('lecturerDashboard.thisWeekSchedule')}</h2>
        {loading ? (
          <div className="text-center py-8 text-gray-500">{t('lecturerDashboard.loadingSchedule')}</div>
        ) : thisWeekItems.length === 0 ? (
          <div className="text-center py-8 text-gray-500">{t('lecturerDashboard.noClasses')}</div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {thisWeekItems.map(item => {
              // Combine date and time to create meeting datetime
              const meetingDateTime = item.actualDate ? new Date(item.actualDate) : null;
              if (meetingDateTime && item.startTime) {
                const [hours, minutes] = item.startTime.split(':').map(Number);
                meetingDateTime.setHours(hours, minutes, 0, 0);
              }

              return (
              <button
                key={item.id}
                type="button"
                onClick={() =>
                  setSelectedMeeting({
                    meetingId: item.meetingId,
                    classId: item.classId,
                    title: `${item.courseCode} • ${item.courseName}`,
                    subtitle: `Week ${item.weekNumber}`,
                    dateLabel: item.actualDate?.toLocaleDateString('id-ID', {
                      weekday: 'short',
                      day: 'numeric',
                      month: 'short',
                    }),
                    meetingDateTime: meetingDateTime || undefined,
                    topic: item.topic || undefined,
                  })
                }
                className="text-left p-3 border border-gray-200 rounded-lg hover:bg-gray-50 transition-colors flex flex-col cursor-pointer"
              >
                <div className="flex-1">
                  <div className="flex items-start justify-between gap-2 mb-2">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="inline-block px-2.5 py-0.5 bg-primary-100 text-primary-700 text-xs font-semibold rounded">
                        {item.weekDay}
                      </span>
                      {item.actualDate && (
                        <span className="text-xs text-gray-500 px-2 py-0.5 bg-gray-100 rounded">
                          {item.actualDate.toLocaleDateString('id-ID', { day: 'numeric', month: 'short' })}
                        </span>
                      )}
                    </div>
                      <span className="text-xs text-gray-500">{t('lecturerDashboard.week')} {item.weekNumber}</span>
                  </div>
                  <div className="text-xs font-semibold text-primary-600 mb-1">{item.courseCode}</div>
                  <h3 className="text-xs font-medium text-gray-900 line-clamp-2 mb-1">{item.courseName}</h3>
                </div>
                <div className="flex flex-col gap-1 text-xs text-gray-600 border-t border-gray-100 pt-2 mt-2">
                  <div className="flex items-center gap-1.5">
                    <Clock className="h-3 w-3 flex-shrink-0" />
                    <span>{item.startTime} - {item.endTime}</span>
                  </div>
                </div>
              </button>
              );
            })}
          </div>
        )}
      </div>

      <AttendanceModal
        selectedMeeting={selectedMeeting}
        onClose={() => setSelectedMeeting(null)}
      />
    </div>
  );
};

export default LecturerDashboard;
